mapper.select:
SELECT task.id AS task_id, task.task_no, meter.id AS meter_id, meter.meter_no, meter.meter_name, task.executor_type, CASE task.executor_type WHEN 'METER_READER' THEN task.meter_reader_id WHEN 'DEVICE' THEN task.device_id END AS executor_id, CASE task.executor_type WHEN 'METER_READER' THEN reader.display_name WHEN 'DEVICE' THEN device.device_name END AS executor_name, task.task_status, task.scheduled_at, task.retry_count, task.version, task.updated_at FROM meter_reading_task AS task INNER JOIN meter ON meter.id = task.meter_id LEFT JOIN sys_user AS reader ON reader.id = task.meter_reader_id AND task.executor_type = 'METER_READER' LEFT JOIN device ON device.id = task.device_id AND task.executor_type = 'DEVICE' WHERE 1 = 1
AND ( task.task_no LIKE CONCAT('%', #{keyword}, '%') OR meter.meter_no LIKE CONCAT('%', #{keyword}, '%') OR meter.meter_name LIKE CONCAT('%', #{keyword}, '%') )
AND task.executor_type = #{executorType}
AND task.task_status = #{taskStatus}
AND task.meter_reader_id = #{meterReaderId}
AND task.device_id = #{deviceId}
AND task.scheduled_at >= #{scheduledAtStart}
AND task.scheduled_at <= #{scheduledAtEnd}
ORDER BY task.scheduled_at DESC, task.id DESC
